 h,w=m.shape; seen=np.zeros_like(m); out=[]
 for y,x in zip(*np.where(m)):
  if seen[y,x]: continue
  q=[(y,x)];seen[y,x]=1; pts=[]
  while q:
   yy,xx=q.pop();pts.append((yy,xx))
   for dy in (-1,0,1):
    for dx in (-1,0,1):
     y2,x2=yy+dy,xx+dx
     if 0<=y2<h and 0<=x2<w and m[y2,x2] and not seen[y2,x2]:seen[y2,x2]=1;q.append((y2,x2))
  out.append(pts)
 return sorted(out,key=len,reverse=True)
for t in range(0,41):
 d=np.max(abs(A[t]-B),2)
 m=d>25
 comps=cc(m)
 vals=[]
 for p in comps[:6]:
  if len(p)<8:continue
  y=np.array([z[0] for z in p]);x=np.array([z[1] for z in p]); vals.append((len(p),(x.min(),y.min(),x.max(),y.max()),(round(x.mean(),1),round(y.mean(),1))))
